export function createChart(trackId, difficulty) {
  if (difficulty === 'beast') {
    const chart = createChart(trackId, 'hard');
    const groups = new Map();
    for (const note of chart.notes) {
      if (!groups.has(note.time)) groups.set(note.time, []);
      groups.get(note.time).push(note);
    }
    const times = [...groups.keys()];
    const notes = [];
    times.forEach((time, index) => {
      const group = groups.get(time);
      const lane = group[0].lane;
      notes.push(...group);
      if (index >= 8 && index % 7 === 0 && group.length === 1) notes.push({ time, lane: (lane + 2) % 4 });
      const next = times[index + 1];
      const gap = next - time;
      if (index >= 4 && index % 4 !== 1 && gap >= Math.max(.20, chart.step * 1.65)) {
        const fill = [1, 2, 3].map(shift => (lane + shift) % 4).find(candidate =>
          !notes.slice(-2).some(note => note.time === time && note.lane === candidate) &&
          !groups.get(next).some(note => note.lane === candidate));
        if (fill !== undefined) notes.push({ time: time + gap / 2, lane: fill });
      }
    });
    return { ...chart, notes };
  }
  const featured = featuredCharts[trackId]?.[difficulty];
  if (featured) return { ...featured, notes: featured.notes.map(([time, lane]) => ({ time, lane })) };
  if (trackId === "gacha") return { notes: gachaCharts[difficulty].map(([time, lane]) => ({ time, lane })), duration: 154.41, step: .15 };
  const track = tracks[trackId];
  const step = 60 / track.bpm / 4;
  const laneOrder = laneOrders[["cave", "fuzz", "claw"].indexOf(trackId)];
  const notes = [];
  for (let bar = 0; bar < bars; bar++) {
    let pattern = track.patterns[bar < 2 ? 0 : 1 + ((bar - 2) % 3)];
    if (difficulty === 'easy') pattern = bar < 2 ? [0, 8] : track.patterns[0];
    if (difficulty === 'hard' && bar >= 2) {
      const fills = bar % 2 ? [2, 6, 14] : [2, 10, 14];
      pattern = [...new Set([...pattern, ...fills])].sort((a, b) => a - b);
    }
    pattern.forEach((pulse, index) => {
      const lane = laneOrder[(index + bar * 2 + Math.floor(bar / 4)) % laneOrder.length];
      const time = (bar * pulsesPerBar + pulse) * step;
      notes.push({ lane, time });
      if (difficulty === 'hard' && bar >= 3 && pulse === (bar % 2 ? 12 : 0)) {
        notes.push({ lane: (lane + 2) % 4, time });
      }
    });
  }
  return { notes, duration: bars * pulsesPerBar * step, step };
}

export function createRound(chart, difficulty, reverseEnabled = false) {
  const remaining = [[], [], [], []];
  for (const note of chart.notes) remaining[note.lane].push(note);
  const positions = [0, 0, 0, 0];
  const settled = new Set();
  const counts = { perfect: 0, great: 0, good: 0, miss: 0 };
  const windows = levels[difficulty];
  let score = 0;
  let claws = 0;
  let perfectCharge = 0;
  let lastBreak = null;
  let reverses = 0;

  function reverse(time) {
    if (!canReverse(time)) return false;
    claws--;
    combo = lastBreak.combo;
    lastBreak = null;
    reverses++;
    return true;
  }

  function canReverse(time) {
    return claws > 0 && lastBreak !== null && time - lastBreak.time <= 2;
  }
  let combo = 0;
  let maxCombo = 0;
  let judged = 0;
  let weighted = 0;
  const multiplier = () => Math.min(4, 1 + Math.floor(combo / 8));

  function settle(note, grade, bonus = 1) {
    settled.add(note);
    const { lane } = note;
    while (settled.has(remaining[lane][positions[lane]])) positions[lane]++;
    counts[grade]++;
    judged++;
    weighted += grades[grade].weight;
    if (grade !== 'miss') {
      lastBreak = null;
      combo++;
      if (reverseEnabled && grade === 'perfect' && claws < 3 && ++perfectCharge === 8) {
        claws++;
        perfectCharge = 0;
      }
    }
    maxCombo = Math.max(maxCombo, combo);
    score += grades[grade].points * multiplier() * bonus;
    return { note, grade };
  }

  function advance(time) {
    const missed = [];
    for (let lane = 0; lane < remaining.length; lane++) {
      for (let note = remaining[lane][positions[lane]]; note && time - note.time > windows.good; note = remaining[lane][positions[lane]]) {
        lastBreak = reverseEnabled && combo > 0 ? { combo, time: note.time + windows.good } : null;
        combo = 0;
        missed.push(settle(note, 'miss'));
      }
    }
    return missed;
  }

  function hit(lane, time, bonus = 1) {
    let closest;
    let delta;
    for (let index = positions[lane]; index < remaining[lane].length; index++) {
      const note = remaining[lane][index];
      const offset = time - note.time;
      if (offset < -windows.good) break;
      if (offset <= windows.good && !settled.has(note) && (!closest || Math.abs(offset) < Math.abs(delta))) {
        closest = note;
        delta = offset;
      }
    }
    if (!closest) {
      lastBreak = null;
      combo = 0;
      return { grade: 'off' };
    }
    const distance = Math.abs(delta);
    const grade = distance <= windows.perfect ? 'perfect' : distance <= windows.great ? 'great' : 'good';
    return { ...settle(closest, grade, bonus), delta };
  }

  function stats() {
    return { score, combo, maxCombo, judged, claws, perfectCharge, reverses, accuracy: judged ? weighted / judged : null, multiplier: multiplier(), counts: { ...counts } };
  }
  return { advance, hit, stats, reverse, canReverse };
}

export function rank(accuracy) {
  if (accuracy >= .98) return 'S';
  if (accuracy >= .9) return 'A';
  if (accuracy >= .8) return 'B';
  if (accuracy >= .65) return 'C';
  return 'D';
}
